python3 -c "
import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-switch/SeasonLookup.bpmn')
root = tree.getroot()

NS = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'xsi': 'http://www.w3.org/2001/XMLSchema-instance',
}

errors = []

# 1. Root is definitions with BPMN namespace
tag = root.tag
assert 'definitions' in tag, 'Root is not definitions'

# Collect all ids
all_ids = {el.get('id') for el in root.iter() if el.get('id')}

# Get process
proc = root.find('bpmn:process', NS)
assert proc is not None, 'No bpmn:process found'

# Collect flow nodes by id
flow_elements = {}
for el in proc:
    eid = el.get('id')
    if eid:
        flow_elements[eid] = el

# 2. Check BPMNDiagram exists
diagram = root.find('bpmndi:BPMNDiagram', NS)
assert diagram is not None, 'No BPMNDiagram'
plane = diagram.find('bpmndi:BPMNPlane', NS)
assert plane is not None, 'No BPMNPlane'

shaped = {s.get('bpmnElement') for s in plane.findall('bpmndi:BPMNShape', NS)}
edged = {e.get('bpmnElement') for e in plane.findall('bpmndi:BPMNEdge', NS)}

# Collect sequence flows
seq_flows = {el.get('id'): el for el in proc.findall('bpmn:sequenceFlow', NS)}
flow_nodes = {k: v for k, v in flow_elements.items() if k not in seq_flows}

# Every flow node has a shape
for nid in flow_nodes:
    if nid not in shaped:
        errors.append(f'MISSING_SHAPE: {nid}')

# Every sequence flow has an edge
for fid in seq_flows:
    if fid not in edged:
        errors.append(f'MISSING_EDGE: {fid}')

# 3. Every sourceRef/targetRef resolves
for fid, flow in seq_flows.items():
    src = flow.get('sourceRef')
    tgt = flow.get('targetRef')
    if src not in all_ids:
        errors.append(f'UNRESOLVED_SOURCE: {src} in {fid}')
    if tgt not in all_ids:
        errors.append(f'UNRESOLVED_TARGET: {tgt} in {fid}')

# 4. XOR gateway checks
for el in proc.findall('bpmn:exclusiveGateway', NS):
    gid = el.get('id')
    default_flow = el.get('default')
    outgoing = [o.text.strip() for o in el.findall('bpmn:outgoing', NS)]
    conditioned = 0
    unconditioned = 0
    for fid in outgoing:
        flow = seq_flows.get(fid)
        if flow is None:
            errors.append(f'MISSING_FLOW: {fid} referenced in gateway {gid}')
            continue
        cond = flow.find('bpmn:conditionExpression', NS)
        if cond is not None:
            conditioned += 1
        else:
            unconditioned += 1
    if default_flow is None:
        errors.append(f'GW_NO_DEFAULT: {gid}')
    else:
        if default_flow not in outgoing:
            errors.append(f'GW_DEFAULT_NOT_IN_OUTGOING: {gid}')
    non_default = [f for f in outgoing if f != default_flow]
    for fid in non_default:
        flow = seq_flows.get(fid)
        if flow is not None and flow.find('bpmn:conditionExpression', NS) is None:
            errors.append(f'MISSING_CONDITION_EXPRESSION: flow {fid} from gateway {gid}')

# 5. No activity/event with more than one incoming flow
for el in proc:
    inc = el.findall('bpmn:incoming', NS)
    if len(inc) > 1:
        errors.append(f'FAKE_JOIN or multiple incoming: {el.get(\"id\")}')

# 6. Superfluous gateway (1 in, 1 out)
for el in proc.findall('bpmn:exclusiveGateway', NS):
    inc = el.findall('bpmn:incoming', NS)
    out = el.findall('bpmn:outgoing', NS)
    if len(inc) == 1 and len(out) == 1:
        errors.append(f'SUPERFLUOUS_GATEWAY: {el.get(\"id\")}')

if errors:
    for e in errors:
        print('ERROR:', e)
    exit(1)
else:
    print('VALID (structural checklist passed)')
    print(f'  flow nodes: {list(flow_nodes.keys())}')
    print(f'  sequence flows: {list(seq_flows.keys())}')
    print(f'  shapes: {shaped}')
    print(f'  edges: {edged}')
" 2>&1

